40	func newAttachCmd() *cobra.Command {
41		var (
42			force     bool
43			agentFlag string
44		)
45		cmd := &cobra.Command{
46			Use:   "attach <session-id>",
47			Short: "Attach an existing agent session",
48			Long: `Attach an existing agent session that wasn't captured by hooks.
49	
50	This creates a checkpoint from the session's transcript and links it to the
51	last commit. Use this when hooks failed to fire or weren't installed when
52	the session started, or to attach a research session.
53	
54	If the last commit already has a checkpoint, the session is added to it.
55	Otherwise a new checkpoint is created.
56	
57	Works with any registered agent, including external agents enabled via
58	external_agents in settings. Run 'entire agent list' to see the full list.`,
59			RunE: func(cmd *cobra.Command, args []string) error {
60				if len(args) != 1 {
61					return cmd.Help()
62				}
63				if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
64					return nil
65				}
66				// Discover external agents so --agent <external-name> is recognized
67				// and so auto-detection can find transcripts from external agents.
68				external.DiscoverAndRegister(cmd.Context())
69				agentName := types.AgentName(agentFlag)
70				return runAttach(cmd.Context(), cmd.OutOrStdout(), args[0], agentName, force)
71			},
72		}
73		cmd.Flags().BoolVarP(&force, "force", "f", false, "Skip confirmation and amend the last commit with the checkpoint trailer")
74		cmd.Flags().StringVarP(&agentFlag, "agent", "a", string(agent.DefaultAgentName), "Agent that created the session (see 'entire agent list' for registered agents, including external)")
75		return cmd
76	}
