78	func runAttach(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, force bool) error {
79		// Initialize structured logger so logging.Warn/Info write to .entire/logs/ not stderr.
80		if err := logging.Init(ctx, sessionID); err != nil {
81			// Init failed — logging will use stderr fallback, non-fatal.
82			_ = err
83		}
84		defer logging.Close()
85	
86		logCtx := logging.WithComponent(ctx, "attach")
87	
88		// Open repository once — shared across all operations.
89		repo, err := openRepository(ctx)
90		if err != nil {
91			return err
92		}
93	
94		existingState, err := validateAttachPreconditions(ctx, repo, sessionID)
95		if err != nil {
96			return err
97		}
98	
99		headCommit, err := getHeadCommit(repo)
100		if err != nil {
101			return err
102		}
103	
104		// If session already has a checkpoint, just offer to link it.
105		if existingState != nil && !existingState.LastCheckpointID.IsEmpty() {
106			cpID := existingState.LastCheckpointID.String()
107			fmt.Fprintf(w, "Session %s already has checkpoint %s\n", sessionID, cpID)
108			if err := promptAmendCommit(logCtx, w, headCommit, cpID, force); err != nil {
109				logging.Warn(logCtx, "failed to amend commit", "error", err)
110				fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", cpID)
111			}
112			return nil
113		}
114	
115		// Resolve agent and transcript path.
116		ag, transcriptPath, err := resolveAgentAndTranscript(logCtx, w, sessionID, agentName, existingState)
117		if err != nil {
118			return err
119		}
120	
121		transcriptData, err := ag.ReadTranscript(transcriptPath)
122		if err != nil {
123			return fmt.Errorf("failed to read transcript: %w", err)
124		}
125	
126		// Normalize Gemini transcripts for storage.
127		storedTranscript := transcriptData
128		if ag.Type() == agent.AgentTypeGemini {
129			if normalized, normErr := geminicli.NormalizeTranscript(transcriptData); normErr == nil {
130				storedTranscript = normalized
131			} else {
132				logging.Warn(logCtx, "failed to normalize Gemini transcript, storing raw", "error", normErr)
133			}
134		}
135	
136		meta := extractTranscriptMetadata(transcriptData)
137	
138		// Determine checkpoint ID: reuse from HEAD if one exists, otherwise generate new.
139		checkpointID, isExistingCheckpoint := resolveCheckpointID(headCommit)
140	
141		// If HEAD references an existing checkpoint, make sure we have it locally
142		// before writing — otherwise we'd create a fresh session 0 under the same
143		// ID and overwrite the original on push.
144		repo, err = ensureCheckpointAvailable(ctx, logCtx, repo, checkpointID, isExistingCheckpoint)
145		if err != nil {
146			return err
147		}
148	
149		// Write directly to entire/checkpoints/v1.
150		store := cpkg.NewGitStore(repo)
151	
152		author, err := GetGitAuthor(ctx)
153		if err != nil {
154			return fmt.Errorf("failed to get git author: %w", err)
155		}
156	
157		var prompts []string
158		if meta.FirstPrompt != "" {
159			prompts = []string{meta.FirstPrompt}
160		}
161	
162		tokenUsage := agent.CalculateTokenUsage(logCtx, ag, transcriptData, 0, "")
163	
164		_, redactSpan := perf.Start(ctx, "redact_transcript")
165		redactedTranscript, redactErr := redact.JSONLBytes(storedTranscript)
166		redactSpan.End()
167		if redactErr != nil {
168			return fmt.Errorf("failed to redact transcript: %w", redactErr)
169		}
170	
171		writeOpts := cpkg.WriteCommittedOptions{
172			CheckpointID: checkpointID,
173			SessionID:    sessionID,
174			Strategy:     strategy.StrategyNameManualCommit,
175			Transcript:   redactedTranscript,
176			Prompts:      prompts,
177			AuthorName:   author.Name,
178			AuthorEmail:  author.Email,
179			Agent:        ag.Type(),
180			Model:        meta.Model,
181			TokenUsage:   tokenUsage,
182		}
183	
184		if compacted := compactTranscriptForStartLine(logCtx, redactedTranscript.Bytes(), cpkg.CommittedMetadata{
185			CheckpointID: checkpointID,
186			Agent:        ag.Type(),
187		}, 0); compacted != nil {
188			writeOpts.CompactTranscript = compacted
189		}
190	
191		v2 := settings.CheckpointsVersion(logCtx) == 2
192		if !v2 {
193			if err := store.WriteCommitted(ctx, writeOpts); err != nil {
194				return fmt.Errorf("failed to write checkpoint: %w", err)
195			}
196		}
197		// IsCheckpointsV2Enabled is true whenever v2 writes are enabled, including
198		// both v2-only mode (checkpoints_version == 2) and dual-write mode. Only
199		// v2-only mode propagates the error.
200		if settings.IsCheckpointsV2Enabled(logCtx) {
201			if err := writeAttachCheckpointV2(logCtx, repo, writeOpts); err != nil {
202				if v2 {
203					return fmt.Errorf("failed to write checkpoint to v2: %w", err)
204				}
205				logging.Warn(logCtx, "attach v2 dual-write failed", "error", err)
206			}
207		}
208	
209		// Create or update session state.
210		if err := saveAttachSessionState(logCtx, existingState, sessionID, ag.Type(), transcriptPath, checkpointID, meta, tokenUsage); err != nil {
211			logging.Warn(logCtx, "failed to save session state", "error", err)
212		}
213	
214		fmt.Fprintf(w, "Attached session %s\n", sessionID)
215		if isExistingCheckpoint {
216			fmt.Fprintf(w, "  Added to existing checkpoint %s\n", checkpointID)
217			return nil
218		}
219	
220		fmt.Fprintf(w, "  Created checkpoint %s\n", checkpointID)
221		cpIDStr := checkpointID.String()
222		if err := promptAmendCommit(logCtx, w, headCommit, cpIDStr, force); err != nil {
223			logging.Warn(logCtx, "failed to amend commit", "error", err)
224			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", cpIDStr)
225		}
226	
227		return nil
228	}
