230	// writeAttachCheckpointV2 writes attach-created checkpoints into the v2 refs.
231	func writeAttachCheckpointV2(ctx context.Context, repo *git.Repository, opts cpkg.WriteCommittedOptions) error {
232		v2URL, err := remote.FetchURL(ctx)
233		if err != nil {
234			logging.Debug(ctx, "attach: using origin for v2 store fetch remote",
235				slog.String("error", err.Error()),
236			)
237		}
238		v2Store := cpkg.NewV2GitStore(repo, v2URL)
239		if err := v2Store.WriteCommitted(ctx, opts); err != nil {
240			return fmt.Errorf("v2 write committed: %w", err)
241		}
242		return nil
243	}
