245	// getHeadCommit returns the HEAD commit object.
246	func getHeadCommit(repo *git.Repository) (*object.Commit, error) {
247		headRef, err := repo.Head()
248		if err != nil {
249			return nil, fmt.Errorf("failed to get HEAD: %w", err)
250		}
251		commit, err := repo.CommitObject(headRef.Hash())
252		if err != nil {
253			return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
254		}
255		return commit, nil
256	}
257	
258	// ensureCheckpointAvailable makes sure the checkpoint referenced by HEAD is
259	// present locally before the attach writes to it. Without this guard, attach
260	// would create a fresh session 0 under the same ID and overwrite the original
261	// session data on push.
262	//
263	// Only the local branch counts — remote-tracking presence is not enough.
264	// If only the remote-tracking ref exists, a subsequent WriteCommitted creates
265	// a brand-new orphan local branch with an empty tree, which would clobber
266	// the remote on push.
267	//
268	// Fast path: check local refs directly — no network. If missing, trigger the
269	// metadata fetch fallback chain used by `entire resume` (which advances the
270	// local ref on success) and re-check. Returns a possibly-freshly-opened repo
271	// handle so go-git sees any newly fetched packfiles.
272	func ensureCheckpointAvailable(ctx, logCtx context.Context, repo *git.Repository, checkpointID id.CheckpointID, isExistingCheckpoint bool) (*git.Repository, error) {
273		if !isExistingCheckpoint {
274			return repo, nil
275		}
276	
277		v2Only := settings.CheckpointsVersion(logCtx) == 2
278	
279		present, readErr := checkpointPresentLocally(ctx, repo, checkpointID, v2Only)
280		if readErr != nil {
281			return repo, fmt.Errorf("failed to read checkpoint %s: %w", checkpointID, readErr)
282		}
283		if present {
284			return repo, nil
285		}
286	
287		// Missing locally — try to refresh, then re-check. Use the same fetch
288		// chain `entire resume` uses for the active storage version (v2 refs live
289		// under refs/entire/, not refs/heads/, so v1 and v2 need different
290		// refspecs).
291		freshRepo, fetchErr := refreshCheckpointRefs(ctx, v2Only)
292		if fetchErr != nil {
293			logging.Warn(logCtx, "failed to refresh metadata branch before attach; proceeding with local state",
294				slog.String("error", fetchErr.Error()))
295		} else {
296			repo = freshRepo
297			present, readErr = checkpointPresentLocally(ctx, repo, checkpointID, v2Only)
298			if readErr != nil {
299				return repo, fmt.Errorf("failed to read checkpoint %s after refresh: %w", checkpointID, readErr)
300			}
301			if present {
302				return repo, nil
303			}
304		}
305	
306		branchDescription := "entire/checkpoints/v1 branch"
307		if v2Only {
308			branchDescription = "v2 /main ref"
309		}
310		return repo, fmt.Errorf(
311			"checkpoint %s referenced by HEAD is missing from the local %s after a refresh attempt. Creating a fresh checkpoint here would overwrite the original session data on push. Run:\n\n    %s\n\nthen re-run attach. If the colleague who made this commit hasn't pushed their checkpoint metadata yet, ask them to do so first",
312			checkpointID.String(), branchDescription, suggestCheckpointFetchCommand(logCtx, v2Only),
313		)
314	}
315	
316	// refreshCheckpointRefs runs the resume-equivalent fetch chain for the storage
317	// version we're about to write to. Returns a freshly-opened repo so go-git
318	// sees any newly-fetched packfiles and ref updates.
319	func refreshCheckpointRefs(ctx context.Context, v2Only bool) (*git.Repository, error) {
320		if v2Only {
321			_, repo, err := getV2MetadataTree(ctx)
322			return repo, err
323		}
324		_, repo, err := getMetadataTree(ctx)
325		return repo, err
326	}
327	
328	// checkpointPresentLocally reports whether the checkpoint already exists on
329	// the local ref we would write to. For v1 / dual-write, that's the local
330	// entire/checkpoints/v1 branch (remote-tracking alone is not enough — see
331	// ensureCheckpointAvailable). For v2-only mode, it's the v2 /main ref, which
332	// has no remote-tracking analog and is therefore already local-only by
333	// construction.
334	func checkpointPresentLocally(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID, v2Only bool) (bool, error) {
335		if v2Only {
336			v2URL, urlErr := remote.FetchURL(ctx)
337			if urlErr != nil {
338				logging.Debug(ctx, "attach: using origin for v2 store fetch remote",
339					slog.String("error", urlErr.Error()),
340				)
341			}
342			summary, err := cpkg.NewV2GitStore(repo, v2URL).ReadCommitted(ctx, checkpointID)
343			if err != nil {
344				return false, err //nolint:wrapcheck // Caller wraps with checkpoint ID context
345			}
346			return summary != nil, nil
347		}
348	
349		localRef := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
350		if _, err := repo.Reference(localRef, true); err != nil {
351			// Local branch ref doesn't exist — treat as "not present locally".
352			// We deliberately do not fall back to remote-tracking: see
353			// ensureCheckpointAvailable's docstring.
354			return false, nil //nolint:nilerr // Missing ref is the "absent" signal, not an error.
355		}
356		summary, err := cpkg.NewGitStore(repo).ReadCommitted(ctx, checkpointID)
357		if err != nil {
358			return false, err //nolint:wrapcheck // Caller wraps with checkpoint ID context
359		}
360		return summary != nil, nil
361	}
362	
363	// suggestCheckpointFetchCommand returns a git fetch command the user can
364	// paste to pull the missing metadata ref. v2 refs live under refs/entire/
365	// (not refs/heads/), so they need an explicit fully-qualified refspec;
366	// v1 lives on a regular branch and its short name is enough.
367	func suggestCheckpointFetchCommand(ctx context.Context, v2Only bool) string {
368		ref := "entire/checkpoints/v1:entire/checkpoints/v1"
369		if v2Only {
370			ref = paths.V2MainRefName + ":" + paths.V2MainRefName
371		}
372		if remote.Configured(ctx) {
373			if url, err := remote.FetchURL(ctx); err == nil && url != "" {
374				return fmt.Sprintf("git fetch %s %s", url, ref)
375			}
376		}
377		return "git fetch origin " + ref
378	}
