442	// validateAttachPreconditions checks session ID format and git repo state.
443	// Returns the existing session state if the session is already tracked (nil if new).
444	func validateAttachPreconditions(ctx context.Context, repo *git.Repository, sessionID string) (*session.State, error) {
445		if err := validation.ValidateSessionID(sessionID); err != nil {
446			return nil, fmt.Errorf("invalid session ID: %w", err)
447		}
448	
449		if strategy.IsEmptyRepository(repo) {
450			return nil, errors.New("repository has no commits yet — make an initial commit before running attach")
451		}
452	
453		store, err := session.NewStateStore(ctx)
454		if err != nil {
455			return nil, fmt.Errorf("failed to open session store: %w", err)
456		}
457		existing, err := store.Load(ctx, sessionID)
458		if err != nil {
459			return nil, fmt.Errorf("failed to check existing session: %w", err)
460		}
461	
462		return existing, nil
463	}
