465	// resolveAgentAndTranscript resolves the agent and transcript path.
466	// For existing sessions, resolves the agent from session state's AgentType.
467	// For new sessions, uses the --agent flag with auto-detection fallback.
468	func resolveAgentAndTranscript(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, existingState *session.State) (agent.Agent, string, error) {
469		ag, err := resolveAgent(existingState, agentName)
470		if err != nil {
471			return nil, "", err
472		}
473	
474		transcriptPath, err := resolveAndValidateTranscript(ctx, sessionID, ag)
475		if err != nil {
476			// Auto-detect: try all other agents.
477			detectedAg, detectedPath, detectErr := detectAgentByTranscript(ctx, sessionID, agentName)
478			if detectErr != nil {
479				return nil, "", fmt.Errorf("%w (also tried auto-detecting other agents: %w)", err, detectErr)
480			}
481			ag = detectedAg
482			transcriptPath = detectedPath
483			logging.Info(ctx, "auto-detected agent from transcript", "agent", ag.Name())
484			fmt.Fprintf(w, "Auto-detected agent: %s\n", ag.Name())
485		}
486	
487		return ag, transcriptPath, nil
488	}
