490	// resolveAgent resolves the agent to use. For existing sessions with an AgentType,
491	// uses agent.GetByAgentType. Otherwise falls back to the --agent flag.
492	func resolveAgent(existingState *session.State, agentName types.AgentName) (agent.Agent, error) {
493		if existingState != nil && existingState.AgentType != "" {
494			ag, err := agent.GetByAgentType(existingState.AgentType)
495			if err == nil {
496				return ag, nil
497			}
498			// Fall through to flag-based resolution.
499		}
500		ag, err := agent.Get(agentName)
501		if err != nil {
502			return nil, fmt.Errorf("agent %q not available: %w", agentName, err)
503		}
504		return ag, nil
505	}
