507	// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
508	// project directories if needed.
509	func resolveAndValidateTranscript(ctx context.Context, sessionID string, ag agent.Agent) (string, error) {
510		transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
511		if err != nil {
512			return "", fmt.Errorf("failed to resolve transcript path: %w", err)
513		}
514		// Only call PrepareTranscript when the file already exists — it flushes
515		// in-progress writes, but can't conjure a file that was never started.
516		// This avoids agents like Cursor polling for 3s on non-existent files
517		// during auto-detection.
518		if _, statErr := os.Stat(transcriptPath); statErr == nil {
519			if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
520				if prepErr := preparer.PrepareTranscript(ctx, transcriptPath); prepErr != nil {
521					logging.Debug(ctx, "PrepareTranscript failed (best-effort)", "error", prepErr)
522				}
523			}
524			return transcriptPath, nil
525		}
526		found, searchErr := searchTranscriptInProjectDirs(sessionID, ag)
527		if searchErr == nil {
528			logging.Info(ctx, "found transcript in alternative project directory", "path", found)
529			return found, nil
530		}
531		logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
532		return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", ag.Name(), sessionID)
533	}
534	
535	// detectAgentByTranscript tries all registered agents (except skip) to find one whose
536	// transcript resolution succeeds for the given session ID.
537	func detectAgentByTranscript(ctx context.Context, sessionID string, skip types.AgentName) (agent.Agent, string, error) {
538		for _, name := range agent.List() {
539			if name == skip {
540				continue
541			}
542			ag, err := agent.Get(name)
543			if err != nil {
544				continue
545			}
546			path, resolveErr := resolveAndValidateTranscript(ctx, sessionID, ag)
547			if resolveErr != nil {
548				logging.Debug(ctx, "auto-detect: agent did not match", "agent", string(name), "error", resolveErr)
549				continue
550			}
551			return ag, path, nil
552		}
553		return nil, "", errors.New("transcript not found for any registered agent")
554	}
555	
556	// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
557	// When force is true, it amends without prompting.
558	func promptAmendCommit(ctx context.Context, w io.Writer, headCommit *object.Commit, checkpointIDStr string, force bool) error {
559		shortHash := headCommit.Hash.String()[:7]
560		subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
561	
562		// Skip amending if this exact checkpoint ID is already in the commit.
563		for _, existing := range trailers.ParseAllCheckpoints(headCommit.Message) {
564			if existing.String() == checkpointIDStr {
565				fmt.Fprintf(w, "Commit %s already has Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
566				return nil
567			}
568		}
569	
570		fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
571	
572		amend := true
573		if !force {
574			if !interactive.CanPromptInteractively() {
575				// Non-interactive: can't prompt, print trailer for manual use.
576				fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
577				return nil
578			}
579			form := NewAccessibleForm(
580				huh.NewGroup(
581					huh.NewConfirm().
582						Title("Amend the last commit in this branch?").
583						Affirmative("Y").
584						Negative("n").
585						Value(&amend),
586				),
587			)
588			if err := form.Run(); err != nil {
589				return fmt.Errorf("prompt failed: %w", err)
590			}
591		}
592	
593		if !amend {
594			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
595			return nil
596		}
597	
598		newMessage := trailers.AppendCheckpointTrailer(headCommit.Message, checkpointIDStr)
599	
600		cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "--only", "-m", newMessage)
601		if output, err := cmd.CombinedOutput(); err != nil {
602			return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
603		}
604	
605		fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
606		return nil
607	}
