425	// Regression for https://github.com/entireio/cli/pull/1014#pullrequestreview-copilot:
426	// Bob clones a repo where Alice's checkpoint is on the remote-tracking ref
427	// (refs/remotes/origin/entire/checkpoints/v1) but the local branch doesn't
428	// exist yet. ReadCommitted falls back to the remote-tracking tree, so a naive
429	// "read and check" guard would think all is well. But WriteCommitted would
430	// then create a *fresh* orphan local branch, and Bob's push would clobber
431	// Alice's data on origin. Attach must refuse in this shape.
432	func TestAttach_RefusesWhenCheckpointOnlyInRemoteTrackingRef(t *testing.T) {
433		setupAttachTestRepo(t)
434	
435		repoRoot := mustGetwd(t)
436		repo, err := git.PlainOpen(repoRoot)
437		if err != nil {
438			t.Fatal(err)
439		}
440	
441		// Seed the local branch with a checkpoint representing Alice's session.
442		alicesCheckpoint := id.MustCheckpointID("abcdef012345")
443		store := cpkg.NewGitStore(repo)
444		if writeErr := store.WriteCommitted(context.Background(), cpkg.WriteCommittedOptions{
445			CheckpointID: alicesCheckpoint,
446			SessionID:    "alice-original",
447			Strategy:     "manual-commit",
448			Transcript:   redact.AlreadyRedacted([]byte(`{"type":"user","message":"hi"}` + "\n")),
449			AuthorName:   "Alice",
450			AuthorEmail:  "alice@example.com",
451		}); writeErr != nil {
452			t.Fatalf("WriteCommitted: %v", writeErr)
453		}
454	
455		// Move the populated branch to the remote-tracking ref, then delete the
456		// local ref. This is the shape `git clone` produces for a branch the user
457		// never explicitly checked out locally.
458		localRef := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
459		remoteTrackingRef := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
460		populated, err := repo.Reference(localRef, true)
461		if err != nil {
462			t.Fatalf("reading local ref: %v", err)
463		}
464		if setErr := repo.Storer.SetReference(plumbing.NewHashReference(remoteTrackingRef, populated.Hash())); setErr != nil {
465			t.Fatalf("SetReference remote-tracking: %v", setErr)
466		}
467		if rmErr := repo.Storer.RemoveReference(localRef); rmErr != nil {
468			t.Fatalf("RemoveReference local: %v", rmErr)
469		}
470	
471		// Amend HEAD so attach treats this as an existing-checkpoint case.
472		runGitInDir(t, repoRoot, "commit", "--amend", "-m", "init\n\nEntire-Checkpoint: "+alicesCheckpoint.String())
473	
474		sessionID := "bob-attempted-attach"
475		setupClaudeTranscript(t, sessionID, `{"type":"user","message":{"role":"user","content":"hi"},"uuid":"u1"}
476	`)
477	
478		var out bytes.Buffer
479		err = runAttach(context.Background(), &out, sessionID, agent.AgentNameClaudeCode, true)
480		if err == nil {
481			t.Fatal("expected attach to refuse when checkpoint is only in the remote-tracking ref")
482		}
483		if !strings.Contains(err.Error(), "missing from the local entire/checkpoints/v1 branch") {
484			t.Errorf("error should explain the local-branch gap; got: %v", err)
485		}
486	
487		// Local branch must still not exist — attach should not have created a
488		// fresh orphan on refuse.
489		if _, refErr := repo.Reference(localRef, true); refErr == nil {
490			t.Error("local entire/checkpoints/v1 branch was created despite refuse; would clobber remote on push")
491		}
492	
493		// Remote-tracking ref must still hold Alice's untouched data.
494		remoteRef, err := repo.Reference(remoteTrackingRef, true)
495		if err != nil {
496			t.Fatalf("remote-tracking ref missing: %v", err)
497		}
498		if remoteRef.Hash() != populated.Hash() {
499			t.Errorf("remote-tracking ref moved from %s to %s", populated.Hash(), remoteRef.Hash())
500		}
501	}
502	
503	// In v2-only mode, the refuse hint must reference the v2 /main ref and
504	// its fully-qualified refspec (refs/entire/checkpoints/v2/main lives under
505	// refs/entire/, not refs/heads/, so a short refspec won't resolve).
506	func TestAttach_RefuseHint_V2Only(t *testing.T) {
507		setupAttachTestRepo(t)
508	
509		repoRoot := mustGetwd(t)
510		setAttachCheckpointsV2Only(t, repoRoot)
511	
512		runGitInDir(t, repoRoot, "commit", "--amend", "-m", "init\n\nEntire-Checkpoint: ffffffffeeee")
513	
514		sessionID := "v2-orphaned-attach"
515		setupClaudeTranscript(t, sessionID, `{"type":"user","message":{"role":"user","content":"hi"},"uuid":"u1"}
516	`)
517	
518		var out bytes.Buffer
519		err := runAttach(context.Background(), &out, sessionID, agent.AgentNameClaudeCode, true)
520		if err == nil {
521			t.Fatal("expected v2-only attach to refuse when checkpoint is missing")
522		}
523		if !strings.Contains(err.Error(), "missing from the local v2 /main ref") {
524			t.Errorf("error should describe the v2 /main ref; got: %v", err)
525		}
526		v2Refspec := paths.V2MainRefName + ":" + paths.V2MainRefName
527		if !strings.Contains(err.Error(), v2Refspec) {
528			t.Errorf("error should include v2 refspec %q; got: %v", v2Refspec, err)
529		}
530		// And must NOT suggest the v1 refspec.
531		if strings.Contains(err.Error(), "entire/checkpoints/v1:entire/checkpoints/v1") {
532			t.Errorf("v2-only hint should not reference the v1 branch; got: %v", err)
533		}
534	}
